#include "stdlib/math/base/special/roundsdf.h"
#include "stdlib/math/base/assert/is_nan.h"
#include "stdlib/math/base/assert/is_infinite.h"
#include "stdlib/math/base/special/pow.h"
#include "stdlib/math/base/special/abs.h"
#include "stdlib/math/base/special/floor.h"
#include "stdlib/math/base/special/ceil.h"
#include "stdlib/math/base/special/log.h"
#include <stdint.h>

/**
* Rounds a double-precision floating-point number to the nearest number toward positive infinity with `n` significant figures.
*
* @param x       number
* @param n       number of significant figures
* @param b       base
* @return        rounded value
*
* @example
* double out = stdlib_base_roundsdf( 3.141592653589793, 3, 10 );
* // returns 3.15
*/
double stdlib_base_roundsdf( const double x, const int32_t n, const int32_t b ) {
	double s;
	double y;
	double m;
	double e;

	if (
		stdlib_base_is_nan( x ) ||
		n < 1
	) {
		return 0.0 / 0.0; // NaN
	}
	if ( stdlib_base_is_infinite( x ) || x == 0.0 ) {
		return x;
	}
	if ( b < 1 ) {
		return 0.0 / 0.0; // NaN
	}

	// Determine the magnitude of the input value:
	e = stdlib_base_floor( stdlib_base_log( stdlib_base_abs( x ) ) / stdlib_base_log( (double)b ) );

	// Determine the scale factor:
	s = stdlib_base_pow( (double)b, (double)( n - (int32_t)e - 1 ) );

	// Scale the input value:
	m = x * s;

	// Round toward positive infinity:
	y = stdlib_base_ceil( m );

	// Rescale:
	return y / s;
}
